20	{%- macro note_field(form_id, label) -%}
21	<label class="field">
22	  <span>{{ label }}</span>
23	  <textarea name="note" rows="2" required>{{ kept(form_id, 'note') }}</textarea>
24	</label>
25	{%- endmacro -%}
