27	{%- macro date_input(form_id, current, required=true) -%}
28	<input type="date" name="scheduled_date" min="{{ today.isoformat() }}"{% if required %} required{% endif %}
29	  value="{{ kept(form_id, 'scheduled_date', current.isoformat() if current else '') }}">
30	{%- endmacro -%}
