32	{#- One editable part of a card: the summary is the thing itself, and opening it shows its form. -#}
33	{%- macro edit(writeup, name, kind, form_ids=none) -%}
34	{% set form_ids = form_ids or [writeup.id ~ "-" ~ name] %}
35	<details class="edit edit-{{ kind }}" name="writeup-{{ writeup.id }}"{% if failed(form_ids) %} open{% endif %}>
36	  {{ caller() }}
37	</details>
38	{%- endmacro -%}
