40	{%- macro event_text(entry) -%}
41	{% set event = entry.event %}
42	{% if event is none %}Filed as {{ entry.writeup.severity | capitalize }}
43	{% elif event.kind == "scheduled" %}Scheduled for {{ event.to_value | day }}
44	{% elif event.kind == "rescheduled" %}Rescheduled from {{ event.from_value | day }} to {{ event.to_value | day }}
45	{% elif event.kind == "unscheduled" %}Unscheduled; was {{ event.from_value | day }}
46	{% elif event.kind == "started" %}Work started
47	{% elif event.kind == "resolved" %}Resolved
48	{% elif event.kind == "canceled" %}Canceled
49	{% elif event.kind == "severity_changed" %}Severity changed from {{ event.from_value | capitalize }} to {{ event.to_value | capitalize }}
50	{% elif event.kind == "description_edited" %}Description changed; was “{{ event.from_value }}”
51	{% endif %}
52	{%- endmacro -%}
