54	<!doctype html>
55	<html lang="en">
56	<head>
57	  <meta charset="utf-8">
58	  <meta name="viewport" content="width=device-width, initial-scale=1">
59	  <title>{% if aircraft %}{{ aircraft.tail_number }} · {% endif %}Fleet clearance</title>
60	  <link rel="stylesheet" href="/static/app.css">
61	</head>
62	<body{% if aircraft %} class="has-panel"{% endif %}>
63	<div class="layout">
64	
65	  <main class="board">
66	    <header class="board-head">
67	      <h1>Fleet clearance</h1>
68	      <p class="summary">
69	        <span class="grounded">{{ board.grounded_count }} grounded</span>
70	        <span class="cleared">{{ board.fleet_size - board.grounded_count }} cleared</span>
71	        <span>{{ board.fleet_size }} aircraft</span>
72	      </p>
73	      <p class="as-of">Status as of <time>{{ now.strftime("%H:%M") }}</time>. Refresh to update.</p>
74	    </header>
75	
76	    <form class="search" method="get" action="/" role="search">
77	      <label for="q">Tail number</label>
78	      <input id="q" name="q" value="{{ query }}" autocomplete="off" spellcheck="false">
79	      {% for group in hidden | sort %}<input type="hidden" name="hide" value="{{ group }}">{% endfor %}
80	      <button class="button">Search</button>
81	      {% if query %}<a href="{{ link(query='', tail='') }}">Clear search</a>{% endif %}
82	    </form>
83	
84	    <table class="fleet">
85	      <thead>
86	        <tr><th scope="col">Aircraft</th><th scope="col">Status and open write-ups</th><th scope="col">Attention</th></tr>
87	      </thead>
88	      {% if query and not board.grounded and not board.cleared %}
89	      <tbody><tr><td colspan="3" class="empty">No aircraft match “{{ query }}”.</td></tr></tbody>
90	      {% else %}
91	      {% for key, label, rows in [("grounded", "Grounded", board.grounded), ("cleared", "Cleared", board.cleared)] %}
92	      {% set is_hidden = key in hidden %}
93	      <tbody class="group group-{{ key }}">
94	        <tr class="group-head">
95	          <th colspan="2" scope="colgroup">{{ label }} <span>{{ rows | length }}</span></th>
96	          <td class="toggle">
97	            <a href="{{ link(toggle=key) }}" aria-label="{{ 'Show' if is_hidden else 'Hide' }} {{ key }} aircraft">{{ "Show" if is_hidden else "Hide" }}</a>
98	          </td>
99	        </tr>
100	        {% if not is_hidden %}
101	        {% for row in rows %}
102	        {% set tail = row.aircraft.tail_number %}
103	        <tr{% if aircraft and aircraft.id == row.aircraft.id %} aria-current="true"{% endif %}>
104	          <th scope="row" class="tail"><a href="{{ link(tail=tail) }}">{{ tail }}</a></th>
105	          <td>
106	            {% if row.cleared %}
107	            <span class="status status-cleared">Cleared</span>
108	            {% else %}
109	            <span class="status status-grounded">Grounded</span>
110	            {% endif %}
111	            {% if row.open_writeups %}
112	            <ul class="row-writeups">
113	              {% for writeup in row.open_writeups %}
114	              <li><span class="severity severity-{{ writeup.severity }}">{{ writeup.severity }}</span><span>{{ writeup.description }}</span></li>
115	              {% endfor %}
116	            </ul>
117	            {% else %}
118	            <p class="no-writeups">No open write-ups</p>
119	            {% endif %}
120	          </td>
121	          <td class="attention">
122	            {%- if row.is_overdue(today) or row.needs_scheduling -%}
123	            <div class="flags">
124	              {% if row.is_overdue(today) %}<span class="flag">Overdue</span>{% endif %}
125	              {% if row.needs_scheduling %}<span class="flag">Needs scheduling</span>{% endif %}
126	            </div>
127	            {%- endif -%}
128	          </td>
129	        </tr>
130	        {% else %}
131	        <tr><td colspan="3" class="empty">{% if query %}No {{ key }} aircraft match “{{ query }}”.{% else %}No aircraft {{ key }}.{% endif %}</td></tr>
132	        {% endfor %}
133	        {% endif %}
134	      </tbody>
135	      {% endfor %}
136	      {% endif %}
137	    </table>
138	  </main>
139	
140	  {% if aircraft %}
141	  <aside class="panel" aria-labelledby="panel-title">
142	    <a class="panel-close" href="{{ link(tail='') }}">
143	      <span class="wide-only">Close</span><span class="narrow-only">Back to fleet</span>
144	    </a>
145	
146	    <header class="panel-head">
147	      <h2 id="panel-title">{{ aircraft.tail_number }}</h2>
148	      {% if status.cleared %}
149	      <p class="status status-cleared">Cleared to fly</p>
150	      <p class="panel-reason">No open High write-ups.</p>
151	      {% else %}
152	      <p class="status status-grounded">Grounded</p>
153	      <p class="panel-reason">{{ status.grounding | length }} open High write-up{{ "s" if status.grounding | length > 1 }} must be resolved or canceled.</p>
154	      {% endif %}
155	    </header>
156	
157	    <details class="file-writeup"{% if failed(["file"]) %} open{% endif %}>
158	      <summary class="button">Create write-up</summary>
159	      <form method="post" action="/aircraft/{{ aircraft.id }}/writeups{{ form_query }}">
160	        {{ error_for(["file"]) }}
161	        <fieldset class="field">
162	          <legend>Severity</legend>
163	          <div class="choices">
164	            {% for severity in ["high", "medium", "low"] %}
165	            <label><input type="radio" name="severity" value="{{ severity }}" required{% if kept('file', 'severity') == severity %} checked{% endif %}> {{ severity | capitalize }}</label>
166	            {% endfor %}
167	          </div>
168	        </fieldset>
169	        <label class="field">
170	          <span>What's wrong</span>
171	          <textarea name="description" rows="3" required>{{ kept("file", "description") }}</textarea>
172	        </label>
173	        <label class="field">
174	          <span>Scheduled date (optional)</span>
175	          {{ date_input("file", none, required=false) }}
176	        </label>
177	        {{ name_field("file", "reported_by") }}
178	        <button class="button">Submit</button>
179	      </form>
180	    </details>
181	
182	    <section class="open-writeups" aria-labelledby="open-title">
183	      <h3 id="open-title">Open write-ups <span>{{ status.open_writeups | length }}</span></h3>
184	      {% for writeup in status.open_writeups %}
185	      {% set id = writeup.id %}
186	      <article class="writeup writeup-{{ writeup.severity }}" id="writeup-{{ id }}">
187	        <div class="card-top">
188	          {% call edit(writeup, "severity", "severity") %}
189	          <summary class="severity severity-{{ writeup.severity }}" aria-label="Severity {{ writeup.severity }}, change it">{{ writeup.severity }}</summary>
190	          <form class="popover" method="post" action="/writeups/{{ id }}/severity{{ form_query }}">
191	            {{ error_for([id ~ "-severity"]) }}
192	            <label class="field">
193	              <span>Change severity to</span>
194	              <select name="severity" required>
195	                <option value="">Choose</option>
196	                {% for severity in ["high", "medium", "low"] if severity != writeup.severity %}
197	                <option value="{{ severity }}"{% if kept(id ~ '-severity', 'severity') == severity %} selected{% endif %}>{{ severity | capitalize }}</option>
198	                {% endfor %}
199	              </select>
200	            </label>
201	            {{ note_field(id ~ "-severity", "Reason") }}
202	            {{ name_field(id ~ "-severity") }}
203	            <button class="button">Change severity</button>
204	          </form>
205	          {% endcall %}
206	
207	          <span class="state">{{ STATUS_LABELS[writeup.status] }}</span>
208	
209	          <div class="corner">
210	            {% if is_overdue(writeup, today) %}<span class="flag">Overdue</span>{% endif %}
211	            {% if writeup.scheduled_date %}
212	            {% call edit(writeup, "schedule", "date", [id ~ "-schedule", id ~ "-unschedule"]) %}
213	            <summary class="date" aria-label="Scheduled {{ writeup.scheduled_date | day }}, reschedule">{{ writeup.scheduled_date | day }}</summary>
214	            <form class="popover popover-end" method="post" action="/writeups/{{ id }}/schedule{{ form_query }}">
215	              {{ error_for([id ~ "-schedule", id ~ "-unschedule"]) }}
216	              <label class="field"><span>Reschedule to</span>{{ date_input(id ~ "-schedule", writeup.scheduled_date) }}</label>
217	              {{ name_field(id ~ "-schedule") }}
218	              <div class="form-actions">
219	                <button class="button">Reschedule</button>
220	                {% if writeup.status == "scheduled" %}
221	                <button class="link-button" formaction="/writeups/{{ id }}/unschedule{{ form_query }}" formnovalidate>Remove date</button>
222	                {% endif %}
223	              </div>
224	            </form>
225	            {% endcall %}
226	            {% else %}
227	            <span class="flag">Needs scheduling</span>
228	            {% endif %}
229	          </div>
230	        </div>
231	
232	        {% call edit(writeup, "description", "description") %}
233	        <summary class="description">{{ writeup.description }}</summary>
234	        <form method="post" action="/writeups/{{ id }}/description{{ form_query }}">
235	          {{ error_for([id ~ "-description"]) }}
236	          <label class="field">
237	            <span>Description</span>
238	            <textarea name="description" rows="3" required>{{ kept(id ~ '-description', 'description', writeup.description) }}</textarea>
239	          </label>
240	          {{ name_field(id ~ "-description") }}
241	          <button class="button">Save description</button>
242	        </form>
243	        {% endcall %}
244	
245	        <p class="meta">#{{ id }} · {{ writeup.reported_by }} · {{ writeup.reported_at | local_time(now) }}</p>
246	
247	        <div class="card-actions">
248	          {% if writeup.status == "unscheduled" %}
249	          {% call edit(writeup, "schedule", "step") %}
250	          <summary class="button">Schedule</summary>
251	          <form method="post" action="/writeups/{{ id }}/schedule{{ form_query }}">
252	            {{ error_for([id ~ "-schedule"]) }}
253	            <label class="field"><span>Scheduled date</span>{{ date_input(id ~ "-schedule", none) }}</label>
254	            {{ name_field(id ~ "-schedule") }}
255	            <button class="button">Schedule</button>
256	          </form>
257	          {% endcall %}
258	          {% elif writeup.status == "scheduled" %}
259	          {% call edit(writeup, "start", "step") %}
260	          <summary class="button">Start work</summary>
261	          <form method="post" action="/writeups/{{ id }}/start{{ form_query }}">
262	            {{ error_for([id ~ "-start"]) }}
263	            {{ name_field(id ~ "-start") }}
264	            <button class="button">Start work</button>
265	          </form>
266	          {% endcall %}
267	          {% else %}
268	          {% call edit(writeup, "resolve", "step") %}
269	          <summary class="button">Resolve</summary>
270	          <form method="post" action="/writeups/{{ id }}/resolve{{ form_query }}">
271	            {{ error_for([id ~ "-resolve"]) }}
272	            {{ note_field(id ~ "-resolve", "What was done") }}
273	            {{ name_field(id ~ "-resolve") }}
274	            <button class="button">Resolve</button>
275	          </form>
276	          {% endcall %}
277	          {% endif %}
278	
279	          {% call edit(writeup, "cancel", "cancel") %}
280	          <summary class="cancel-link">Cancel write-up</summary>
281	          <form class="popover popover-end" method="post" action="/writeups/{{ id }}/cancel{{ form_query }}">
282	            {{ error_for([id ~ "-cancel"]) }}
283	            {{ note_field(id ~ "-cancel", "Why cancel it") }}
284	            {{ name_field(id ~ "-cancel") }}
285	            <button class="button">Cancel write-up</button>
286	          </form>
287	          {% endcall %}
288	        </div>
289	      </article>
290	      {% else %}
291	      <p class="empty">No open write-ups.</p>
292	      {% endfor %}
293	    </section>
294	
295	    <section class="history" aria-labelledby="history-title">
296	      <h3 id="history-title">History</h3>
297	      <ol class="timeline">
298	        {% for entry in timeline %}
299	        <li>
300	          <p class="when"><time>{{ entry.at | local_time(now) }}</time> · {{ entry.actor }}</p>
301	          <p class="what">{{ event_text(entry) }}</p>
302	          {% if entry.event and entry.event.note %}<p class="note">{{ entry.event.note }}</p>{% endif %}
303	          <p class="ref">#{{ entry.writeup.id }} {{ entry.writeup.description }}</p>
304	        </li>
305	        {% else %}
306	        <li class="empty">Nothing has been filed against this aircraft.</li>
307	        {% endfor %}
308	      </ol>
309	    </section>
310	  </aside>
311	  {% endif %}
312	
313	</div>
314	<script src="/static/scroll.js"></script>
315	</body>
316	</html>
