5	@font-face { font-family: "IBM Plex Mono"; font-weight: 500; font-display: swap; src: url("fonts/ibm-plex-mono-500-latin.woff2") format("woff2"); }
6	
7	/* Tokens from tagup.ai's dark theme. Orange means caution only (DECISIONS.md 31). */
8	:root {
9	  color-scheme: dark;
10	  --bg: #030303;
11	  --surface: #0a0e1a;
12	  --raised: #111729;
13	  --fg: #f4f7ff;
14	  --muted: #a9b3c9;
15	  --border: #242b40;
16	  --grounded: #fca5a5;
17	  --grounded-tint: rgb(252 165 165 / 0.07);
18	  --cleared: #7cff6b;
19	  --caution: #ff4f00;
20	  --caution-text: #ff7a3d;
21	
22	  --font-sans: "Barlow", ui-sans-serif, system-ui, sans-serif;
23	  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
24	  --gutter: clamp(1rem, 3vw, 2rem);
25	}
26	
27	*, *::before, *::after { box-sizing: border-box; }
28	
29	html { scrollbar-color: var(--border) var(--bg); }
30	
31	body {
32	  margin: 0;
33	  background: var(--bg);
34	  color: var(--fg);
35	  font: 400 15px/1.45 var(--font-sans);
36	  caret-color: var(--fg);
37	  -webkit-font-smoothing: antialiased;
38	}
39	
40	::selection { background: var(--fg); color: var(--bg); }
41	
42	:focus-visible { outline: 2px solid var(--fg); outline-offset: 2px; }
43	
44	a { color: inherit; text-underline-offset: 0.2em; text-decoration-color: var(--muted); }
45	a:hover { text-decoration-color: var(--fg); }
46	
47	h1, h2, h3, p, ul, ol { margin: 0; }
48	
49	summary { cursor: pointer; list-style: none; }
50	summary::-webkit-details-marker { display: none; }
51	
52	/* Labels and data in mono, as on tagup.ai. */
53	.fleet thead th, .group-head, .status, .flag, .severity, .state, .date,
54	.summary, .search label, .field > span, .field legend, .panel-close, .button,
55	.history h3, .open-writeups h3, .when {
56	  font-family: var(--font-mono);
57	  font-size: 12px;
58	  font-weight: 500;
59	  letter-spacing: 0.06em;
60	  text-transform: uppercase;
61	}
62	
63	/* ---------- Layout ---------- */
64	
65	.layout { min-height: 100vh; }
66	
67	.board {
68	  padding: var(--gutter);
69	  max-width: 72rem;
70	}
71	
72	@media (min-width: 960px) {
73	  .has-panel .layout {
74	    display: grid;
75	    grid-template-columns: minmax(0, 1fr) minmax(24rem, 30rem);
76	  }
77	  .panel {
78	    position: sticky;
79	    top: 0;
80	    height: 100vh;
81	    overflow-y: auto;
82	    border-left: 1px solid var(--border);
83	  }
84	  .narrow-only { display: none; }
85	}
86	
87	@media (max-width: 959.98px) {
88	  .has-panel .board { display: none; }
89	  .wide-only { display: none; }
90	}
91	
92	/* ---------- Board ---------- */
93	
94	.board-head { display: grid; gap: 0.5rem; margin-bottom: 1.5rem; }
95	
96	h1 { font-size: 28px; font-weight: 500; letter-spacing: -0.01em; line-height: 1.1; }
97	
98	.summary { display: flex; flex-wrap: wrap; gap: 0.25rem 1.25rem; font-size: 13px; }
99	.summary .grounded { color: var(--grounded); }
100	.summary .cleared { color: var(--cleared); }
