343	.edit-description > summary:hover { background: var(--raised); }
344	.edit-description > summary:hover::after,
345	.edit-description > summary:focus-visible::after { opacity: 1; }
346	.edit-description[open] > summary { color: var(--muted); }
347	.edit-description[open] > summary::after { content: "Close"; opacity: 1; }
348	.edit-description[open] > form { margin-top: 0.75rem; }
349	@media (hover: none) {
350	  .edit-description > summary::after { opacity: 1; }
351	}
352	
353	.meta { color: var(--muted); font-size: 13px; }
354	
355	.card-actions {
356	  display: flex;
357	  align-items: flex-start;
358	  gap: 1rem;
359	  border-top: 1px solid var(--border);
360	  padding-top: 0.9rem;
361	  margin-top: 0.15rem;
362	}
363	.edit-step { flex: 1; }
364	.edit-step[open] > summary { background-color: var(--border); }
365	.edit-step[open] > form { margin-top: 1rem; }
366	.edit-cancel { margin-left: auto; padding-top: 0.55rem; }
367	.cancel-link { color: var(--muted); font-size: 14px; text-decoration: underline; text-underline-offset: 0.2em; text-decoration-color: var(--border); }
368	.cancel-link:hover, .edit-cancel[open] .cancel-link { color: var(--fg); }
369	
370	/* ---------- History ---------- */
371	
372	.timeline { list-style: none; padding: 0; display: grid; }
373	.timeline li {
374	  display: grid;
375	  gap: 0.15rem;
376	  padding: 0.75rem 0 0.75rem 1rem;
377	  border-left: 1px solid var(--border);
378	  position: relative;
379	}
380	.timeline li::before {
381	  content: "";
382	  position: absolute;
383	  left: -3.5px;
384	  top: 1.1rem;
385	  width: 6px;
386	  height: 6px;
387	  background: var(--muted);
388	}
389	.when { color: var(--muted); font-size: 11px; }
390	.note { color: var(--fg); max-width: 60ch; }
391	.note::before { content: "“"; }
392	.note::after { content: "”"; }
393	.ref { color: var(--muted); font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
394	
395	/* ---------- Narrow screens ---------- */
396	
397	@media (max-width: 640px) {
398	  .fleet thead { display: none; }
399	  .fleet .group-head { display: flex; justify-content: space-between; border-bottom: 1px solid currentColor; }
400	  .fleet .group-head > * { border: 0; }
401	  .fleet tr:not(.group-head) { display: grid; grid-template-columns: auto 1fr; gap: 0.25rem 0.75rem; padding: 0.75rem 0.5rem; border-bottom: 1px solid var(--border); }
402	  .fleet tr:not(.group-head) > * { padding: 0; border: 0; width: auto; }
403	  .fleet tr:not(.group-head) > .attention { grid-column: 2; }
404	  .fleet tr:not(.group-head) > .attention:empty { display: none; }
405	  .row-writeups li { grid-template-columns: 4rem minmax(0, 1fr); }
406	  .search input { flex: 1; width: auto; }
407	}
